reference_solution:
def maximum_activation_total(value,limit):
    groups={}
    for score,bound in zip(value,limit):groups.setdefault(bound,[]).append(score)
    answer=0
    for bound,scores in groups.items():
        scores.sort(reverse=True);answer+=sum(scores[:bound])
    return answer

